components.css:
.ds-context {
  --profile-ink: #3c382f;
  --profile-muted: #655f51;
  --profile-rule: #cbbfa9;
  --notebook-paper: url('https://media.secknow-ai.com/space/textures/gallery/notebook/paper.png');
  --notebook-button: url('https://media.secknow-ai.com/space/textures/gallery/notebook/button.png');
  color: var(--profile-ink);
  font-family: "霞鹜文楷", serif;
}.ds-context button {
  background: none;
  border: none;
  cursor: pointer;
  font: inherit;
  color: inherit;
}.ds-context a {
    color: inherit;
    text-decoration: none;
}.ds-context :focus-visible {
  outline: 2px solid #78603b;
  outline-offset: 3px;
}.ds-context ::selection {
  background: #f4dca5;
  color: #322f29;
}.ds-project-tabs {
  display: flex;
  align-items: flex-end;
  flex-shrink: 0;
  min-height: 54px;
  gap: 3px;
  padding: 5px 26px 0;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-padding-inline: 26px;
}.ds-project-tabs button {
  position: relative;
  flex: 1 0 auto;
  min-height: 46px;
  padding: 10px 14px 12px;
  border: 1px solid #bdb3a0;
  border-bottom: 0;
  border-radius: 9px 12px 0 0;
  background: #f8f5eb var(--notebook-paper) center/100% 100%;
  background-blend-mode: multiply;
  color: var(--profile-muted);
  font-size: 1rem;
  white-space: nowrap;
  transition: color 160ms ease, background-color 160ms ease;
}.ds-project-tabs button:nth-child(even) {
  border-radius: 12px 6px 0 0;
}.ds-project-tabs button:hover {
  background-color: #f3e9d2;
  color: var(--profile-ink);
}.ds-project-tabs button[aria-current] {
  background-color: #f6dca3;
  color: #3f3524;
  font-weight: 600;
}.ds-project-tabs button:focus-visible {
  outline-offset: -5px;
}@media (max-width: 1024px) {
  .ds-project-tabs {
    padding-inline: 20px;
    scroll-padding-inline: 20px;
  }
  .ds-project-tabs button {
    padding-inline: 13px;
  }
}@media (max-width: 700px) {
  .ds-project-tabs {
    min-height: 46px;
    padding: 4px 15px 0;
    scroll-padding-inline: 15px;
  }
  .ds-project-tabs button {
    min-height: 44px;
    padding: 7px 13px 9px;
    font-size: 1rem;
  }
}@media (prefers-reduced-motion: reduce) {
  .ds-project-tabs button {
    transition: none;
  }
}

