.ds-project-notebook {
  container: project-notebook/inline-size;
  display: flex;
  flex-direction: column;
  height: 100%;
  filter: drop-shadow(0 12px 20px rgba(64, 49, 28, 0.17));
}

.ds-project-notebook-sheet {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 0.36fr) minmax(0, 0.64fr);
  flex: 1;
  min-height: 0;
  gap: 32px;
  padding: 25px 24px 27px;
  border: 20px solid transparent;
  border-image: var(--notebook-paper) 48 fill stretch;
  margin-top: -2px;
}

.ds-project-notebook-cover {
  position: relative;
  min-width: 0;
  min-height: 0;
  max-height: 680px;
  margin: 0;
  overflow: hidden;
  border-radius: 7px 11px 6px 9px;
}

.ds-project-notebook-cover img {
  position: absolute;
  inset: auto 0 0;
  display: block;
  width: 100%;
  height: 135%;
  object-fit: cover;
  object-position: center bottom;
}

.ds-project-reading-sheet {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

.ds-project-notebook-heading {
  flex-shrink: 0;
  padding: 4px 16px 0 0;
}

.ds-project-notebook-heading h2 {
  position: relative;
  isolation: isolate;
  width: fit-content;
  max-width: 100%;
  margin: 0;
  font-size: clamp(1.5rem, 2.45vw, 2.25rem);
