  font-size: 1.13rem;
  line-height: 1.7;
  text-wrap: pretty;
}

.ds-project-chapters {
  display: flex;
  flex-shrink: 0;
  gap: 0.55rem;
  padding: 0.2rem 3px 0.45rem;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-padding-inline: 3px;
}

.ds-project-chapters a {
  display: inline-flex;
  flex: 1 0 auto;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.3rem 0.65rem;
  border: 1px solid #bfb29a;
  border-radius: 6px 9px 5px 7px;
