  background-blend-mode: multiply;
  border-color: #ad956b;
}

.ds-project-details-body {
  flex: 1;
  min-height: 0;
  padding: 1.35rem 0.45rem 1.4rem 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scroll-padding-top: 1rem;
  font-size: 1.04rem;
  line-height: 1.85;
}

.ds-project-details-body p {
  margin: 0 0 0.9rem;
  overflow-wrap: anywhere;
}

.ds-project-details-body h3 {
  width: fit-content;
  margin: 0 0 0.9rem;
  padding: 0.05rem 0.45rem;
  font-size: 1.4rem;
  font-weight: 600;
