  background: #e5e9cf;
  border-radius: 7px 3px 9px 4px;
}

.ds-project-details-body h4 {
  margin: 0 0 0.3rem;
  font-size: 1.1rem;
  line-height: 1.5;
  font-weight: 600;
}

@media (max-width: 1024px) {
  .ds-project-notebook-sheet {
    grid-template-columns: minmax(0, 0.3fr) minmax(0, 0.7fr);
    gap: 22px;
    padding: 20px 14px;
    border-width: 15px;
  }
  .ds-project-notebook-heading h2 {
    font-size: 1.75rem;
  }
}

@container project-notebook (max-width: 1100px) {
  .ds-project-notebook-sheet {
    grid-template-columns: clamp(84px, 18cqi, 152px) minmax(0, 1fr);
    grid-template-rows: auto auto minmax(0, 1fr);
    gap: 0 24px;
  }
  .ds-project-notebook-cover {
    grid-area: 1/1;
    align-self: center;
    width: 100%;
    max-height: none;
    aspect-ratio: 1;
  }
  .ds-project-reading-sheet {
    display: contents;
  }
  .ds-project-notebook-heading {
    grid-area: 1/2;
    align-self: center;
    padding: 4px 32px 0 0;
  }
  .ds-project-notebook-heading h2 {
    font-size: 1.75rem;
  }
  .ds-project-notebook-heading p {
    margin: 0.65rem 0 0;
  }
  .ds-project-chapters {
    grid-area: 2/1/auto/-1;
    min-width: 0;
    margin-top: 1rem;
  }
  .ds-project-details-body {
    grid-area: 3/1/auto/-1;
    min-width: 0;
  }
}

@media (max-width: 700px) {
  .ds-project-notebook-sheet {
    column-gap: 14px;
    padding: 18px 12px 10px;
    border-width: 12px;
  }
  .ds-project-notebook-heading {
    padding: 0 20px 0 0;
  }
  .ds-project-notebook-heading h2 {
    font-size: 1.55rem;
    line-height: 1.35;
  }
  .ds-project-notebook-heading p {
    margin: 0.65rem 0 0.85rem;
    font-size: 1rem;
    line-height: 1.6;
  }
  .ds-project-chapters {
    gap: 0.4rem;
    margin-top: 0.85rem;
    padding-bottom: 0.4rem;
  }
  .ds-project-chapters a {
    font-size: 0.95rem;
    padding-inline: 0.6rem;
  }
  .ds-project-details-body {
    padding-top: 1rem;
    font-size: 1rem;
  }
}

@media (max-height: 600px) {
  .ds-project-notebook-sheet {
    padding-block: 10px;
    border-block-width: 10px;
  }
  .ds-project-notebook-heading h2 {
    font-size: 1.4rem;
    line-height: 1.3;
  }
  .ds-project-notebook-heading p {
    margin: 0.4rem 0 0.5rem;
    font-size: 1rem;
    line-height: 1.5;
  }
  .ds-project-chapters {
    margin-top: 0.6rem;
  }
  .ds-project-details-body {
    padding-top: 0.6rem;
  }
  @container project-notebook (max-width: 1100px) {
    .ds-project-notebook-sheet {
      grid-template-columns: clamp(56px, 12cqi, 80px) minmax(0, 1fr);
      column-gap: 14px;
    }
    .ds-project-notebook-cover {
      align-self: start;
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-project-chapters a {
    transition: none;
  }
}
